      );
      const nextWaveIndex = Math.max(0, Math.min(collection.waves.length - 1, currentWaveIndex + delta));
      if (nextWaveIndex === currentWaveIndex && collection.waves.length > 1) {
        statusLine = delta > 0 ? "Already on the last wave." : "Already on the first wave.";
        requestRender();
        return;
      }

      focusWave(nextWaveIndex);
    };

    const setPane = (nextPane: Pane) => {
      pane = nextPane;
      statusLine = `Pane: ${pane}`;
      scheduleRefresh();
      requestRender();
      const version = refreshVersion;
      const targetRunId = runId;
      if (pane === "log") {
        void refreshRunLog(targetRunId, version)
          .then(requestRender)
          .catch((error) => {
            const message = error instanceof Error ? error.message : String(error);
            if (!mounted || version !== refreshVersion || targetRunId !== runId) {
              return;
            }
            runLogLines = [];
            runLogError = `Run log unavailable: ${message}`;
            statusLine = `Run log unavailable: ${message}`;
            requestRender();
          });
      }
      if (pane === "commits") {
        void refreshRunCommits(targetRunId, version)
          .then(requestRender)
          .catch((error) => {
            const message = error instanceof Error ? error.message : String(error);
            if (!mounted || version !== refreshVersion || targetRunId !== runId) {
              return;
            }
            runCommits = [];
            runCommitsBranchName = null;
            runCommitsError = `Run commits unavailable: ${message}`;
            statusLine = `Run commits unavailable: ${message}`;
            requestRender();
          });
      }
    };

    const cyclePane = () => {
      setPane(pane === "output" ? "story" : pane === "story" ? "run" : pane === "run" ? "events" : pane === "events" ? "log" : pane === "log" ? "commits" : "output");
    };

    const toggleHelp = () => {
      showHelp = !showHelp;
      statusLine = showHelp ? "Help open." : `Pane: ${pane}`;
      requestRender();
    };

    const switchToRun = (nextRun: RunListItem | undefined, missingMessage: string) => {
      if (!nextRun) {
        statusLine = missingMessage;
        requestRender();
        return;
      }

      if (nextRun.id === runId) {
        statusLine = `Already focused on run ${runId}.`;
        requestRender();
        return;
      }

      runAction(`Switching to run ${nextRun.id}…`, async () => {
        runId = nextRun.id;
        selectedStoryId = null;
        selectedOutput = null;
        selectedOutputError = null;
        runLogLines = [];
        runLogError = null;
        runCommits = [];
        runCommitsBranchName = null;
        runCommitsError = null;
        workspaceRunsError = null;
      });
    };

    const switchRun = (delta: number) => {
      const currentIndex = workspaceRuns.findIndex((item) => item.id === runId);
      if (currentIndex < 0) {
        statusLine = "Run history is still loading.";
        requestRender();
        return;
      }

      const nextRun = workspaceRuns[currentIndex + delta];
      switchToRun(nextRun, delta > 0 ? "No older workspace run." : "No newer workspace run.");
    };

    const switchToRecentRun = (recentIndex: number) => {
      if (workspaceRuns.length === 0) {
        statusLine = "Run history is still loading.";
        requestRender();
        return;
      }

      switchToRun(workspaceRuns[recentIndex], `No recent run is mapped to ${recentIndex + 1}.`);
    };

    const refreshNow = () => {
      runAction(`Refreshing run ${runId}…`, async () => {
        // runAction performs the sync after the action completes.
      });
    };

    const openRunLog = () => {
      setPane("log");
    };

    const openRunCommits = () => {
      setPane("commits");
    };

    const cancelRun = () => {
      if (!payload || !isCancellableRun(payload.run.status)) {
        return;
      }

      runAction(`Cancelling run ${runId}…`, async () => {
        const confirmed = (await ctx.ui.confirm?.("Cancel run", `Cancel run ${runId}?`)) ?? false;
        if (!confirmed) {
          statusLine = `Cancel aborted for run ${runId}`;
          return;
        }
        await apiFetchJson(baseUrl, `/api/pipeline/runs/${runId}/cancel`, { method: "POST", token });
        notify(ctx.ui, `Cancellation requested for run ${runId}`, "warning");
      });
    };

